DO $$ DECLARE r record; BEGIN FOR r IN SELECT pg_get_serial_sequence(format('%I.%I', table_schema, table_name), column_name) seq, table_schema, table_name, column_name FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('notification_templates','rc_credit_mappings') AND column_name='id' LOOP IF r.seq IS NOT NULL THEN EXECUTE format('SELECT setval(%L, greatest(coalesce(max(%I), 0), 1), true) FROM %I.%I', r.seq, r.column_name, r.table_schema, r.table_name); END IF; END LOOP; END $$;

